import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 16
#define TILE_H 8
#define OC_TILE 8
__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int pad,
    int H_out, int W_out)
{
    extern __shared__ float smem[];
    int patch_h = TILE_H * stride + K - stride;
    int patch_w = TILE_W * stride + K - stride;
    int tile_col = blockIdx.x;
    int tile_row = blockIdx.y;
    int n_oc_groups = (C_out + OC_TILE - 1) / OC_TILE;
    int noc = blockIdx.z;
    int n = noc / n_oc_groups;
    int oc_group = noc % n_oc_groups;
    int oc_base = oc_group * OC_TILE;
    int out_w0 = tile_col * TILE_W;
    int out_h0 = tile_row * TILE_H;
    int tid = threadIdx.x;
    int tx = tid % TILE_W;
    int ty = tid / TILE_W;
    int w_out = out_w0 + tx;
    int h_out = out_h0 + ty;
    int in_h0 = out_h0 * stride - pad;
    int in_w0 = out_w0 * stride - pad;
    bool valid = (h_out < H_out) && (w_out < W_out);
    float sums[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) {
        int co = oc_base + i;
        sums[i] = (valid && co < C_out) ? bias[co] : 0.0f;
    }
    int nthreads = TILE_H * TILE_W;
    int patch_size = patch_h * patch_w;
    for (int c_in = 0; c_in < C_in; ++c_in) {
        const float* input_ptr = input + ((n * C_in + c_in) * H_in) * W_in;
        for (int idx = tid; idx < patch_size; idx += nthreads) {
            int ph = idx / patch_w;
            int pw = idx % patch_w;
            int h_in = in_h0 + ph;
            int w_in = in_w0 + pw;
            float val = 0.0f;
            if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                val = input_ptr[h_in * W_in + w_in];
            }
            smem[idx] = val;
        }
        __syncthreads();
        if (valid) {
            int local_h0 = ty * stride;
            int local_w0 = tx * stride;
            for (int kh = 0; kh < K; ++kh) {
                const float* smem_row = smem + (local_h0 + kh) * patch_w + local_w0;
                #pragma unroll
                for (int kw = 0; kw < K; ++kw) {
                    float val = smem_row[kw];
                    #pragma unroll
                    for (int oc = 0; oc < OC_TILE; ++oc) {
                        int co = oc_base + oc;
                        if (co >= C_out) continue;
                        float wv = weight[((co * C_in + c_in) * K + kh) * K + kw];
                        sums[oc] += val * wv;
                    }
                }
            }
        }
        __syncthreads();
    }
    if (valid) {
        #pragma unroll
        for (int oc = 0; oc < OC_TILE; ++oc) {
            int co = oc_base + oc;
            if (co >= C_out) break;
            int out_idx = ((n * C_out + co) * H_out + h_out) * W_out + w_out;
            output[out_idx] = sums[oc];
        }
    }
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad)
{
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int H_out = (H_in + 2 * pad - K) / stride + 1;
    int W_out = (W_in + 2 * pad - K) / stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    dim3 threads(TILE_W * TILE_H);
    int n_oc_groups = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 blocks((W_out + TILE_W - 1) / TILE_W,
                (H_out + TILE_H - 1) / TILE_H,
                N * n_oc_groups);
    int patch_h = TILE_H * stride + K - stride;
    int patch_w = TILE_W * stride + K - stride;
    size_t smem_size = (size_t)patch_h * (size_t)patch_w * sizeof(float);
    conv2d_kernel<<<blocks, threads, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, stride, pad,
        H_out, W_out
    );
    return output;
}
"""

conv2d_header = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_header,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(96, 3, 11, 11))
        self.bias = nn.Parameter(torch.empty(96))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = 3 * 11 * 11
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)
        self.stride = 4
        self.padding = 2

    def forward(self, x):
        x = x.cuda().contiguous()
        return conv2d_module.conv2d_forward(x, self.weight, self.bias, self.stride, self.padding)


batch_size = 256
num_classes = 1000


def get_inputs():
    return [torch.rand(batch_size, 3, 224, 224)]


def get_init_inputs():
    return [num_classes]

